import subprocess
import platform
import time
def task_func(url):
    if not isinstance(url, str):
        raise TypeError("Invalid URL type")
    elif url == "":
        raise ValueError("URL cannot be empty")
    system = platform.system()
    if system == "Windows":
        command = ["start", url]
    elif system == "Darwin":
        command = ["open", url]
    else:
        command = ["xdg-open", url]
    process = subprocess.Popen(command, shell=True)
    time.sleep(1)
    return process.poll()

