import subprocess
import logging
def task_func(filepath):
    if not os.path.exists(filepath):
        raise FileNotFoundError("Specified file does not exist")
    try:
        compiler = subprocess.check_output(['which', 'g++']).decode().strip()
    except subprocess.CalledProcessError:
        raise FileNotFoundError("C++ compiler not found")
    try:
        result = subprocess.run([compiler, filepath, '-o', 'output'], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        if result.returncode != 0:
            raise subprocess.CalledProcessError(result.returncode, result.args, result.stderr)
        logging.info("Compilation successful")
    except subprocess.CalledProcessError as e:
        logging.error(f"Compilation failed: {e.stderr.decode('utf-8')}")

